import hou, math
V = hou.Vector3
FR = list(range(1, 265))

def clamp(x, a, b): return max(a, min(b, x))
def sst(x):
    x = clamp(x, 0.0, 1.0); return x * x * x * (x * (6 * x - 15) + 10)
def ss(x):
    x = clamp(x, 0.0, 1.0); return x * x * (3 - 2 * x)
def lerp(a, b, t): return a + (b - a) * t
def vlerp(a, b, t): return a + (b - a) * t

def bake(parm, vals):
    parm.deleteAllKeyframes()
    keys = []
    for f, v in vals:
        k = hou.Keyframe(); k.setFrame(f); k.setValue(v)
        k.setExpression('linear()', hou.exprLanguage.Hscript)
        keys.append(k)
    parm.setKeyframes(keys)

def bspline(ctrl, u):
    # uniform cubic B-spline, u in [0, len(ctrl)-3]
    n = len(ctrl) - 3
    u = clamp(u, 0.0, float(n))
    i = min(int(math.floor(u)), n - 1)
    t = u - i
    p0, p1, p2, p3 = ctrl[i], ctrl[i + 1], ctrl[i + 2], ctrl[i + 3]
    b0 = (1 - t) ** 3 / 6.0
    b1 = (3 * t ** 3 - 6 * t ** 2 + 4) / 6.0
    b2 = (-3 * t ** 3 + 3 * t ** 2 + 3 * t + 1) / 6.0
    b3 = t ** 3 / 6.0
    return p0 * b0 + p1 * b1 + p2 * b2 + p3 * b3

P = dict(
    T_HAND_START=52, T_HAND_END=98,
    T_HOVER=104, T_DESC=118, T_LAND=132,
    T_LIFT=222, T_HOV2=236, T_AWAY=242,
    HOVER_H=0.09, LAND_OFF=0.0054, HOV2_H=0.06,
    HEAD_LAG=4,
)

girl = hou.node('/obj/girl')
bf = hou.node('/obj/butterfly')
body = bf.node('CTRL_body'); wl = bf.node('CTRL_wing_L'); wr = bf.node('CTRL_wing_R')
hc = hou.node('/obj/hand_contact')

# ---------------- girl: fingers (relaxed, ring/little more curled) ----------------
fing = {'index': (6, 9, 7), 'middle': (8, 11, 8), 'ring': (14, 18, 13), 'little': (18, 22, 15)}
for side in ('left', 'right'):
    for fn, (a, b, c) in fing.items():
        girl.parm('%s%s1rotatex' % (side, fn)).set(a)
        girl.parm('%s%s2rotate' % (side, fn)).set(b)
        girl.parm('%s%s3rotate' % (side, fn)).set(c)
    girl.parm('%sthumb1rotatex' % side).set(4)
    girl.parm('%sthumb2rotate' % side).set(7)
    girl.parm('%sthumb3rotate' % side).set(6)

# ---------------- girl: left hand ----------------
T0 = (-0.31513106711217626, 0.004341544089813493, 0.1780316453785062); R0 = (-30.0, -60.0, 0.0)
T1 = (-0.2682194738001239, 0.203772961455615, 0.26811421313197); R1 = (-55.22732341514463, -38.81371389840019, 21.48962264373169)
REST = T0 + R0; POSE = T1 + R1

def hand_vals(f, t_low):
    w = sst((f - P['T_HAND_START']) / float(P['T_HAND_END'] - P['T_HAND_START']))
    v = [lerp(a, b, w) for a, b in zip(REST, POSE)]
    if t_low is not None:
        w2 = sst((f - t_low) / 48.0)
        v = [lerp(a, b, w2) for a, b in zip(v, REST)]
    return v

hand_names = ['ikwristlefttranslatex', 'ikwristlefttranslatey', 'ikwristlefttranslatez',
              'ikwristleftrotatex', 'ikwristleftrotatey', 'ikwristleftrotatez']

def bake_hand(t_low):
    vals = [hand_vals(f, t_low) for f in FR]
    for i, n in enumerate(hand_names):
        bake(girl.parm(n), [(f, vals[k][i]) for k, f in enumerate(FR)])

bake_hand(None)
# right wrist stays at rest (no keys)
for n in ['ikwristrighttranslatex', 'ikwristrighttranslatey', 'ikwristrighttranslatez',
          'ikwristrightrotatex', 'ikwristrightrotatey', 'ikwristrightrotatez']:
    girl.parm(n).deleteAllKeyframes()

# contact frame (static while hand held)
mc = hc.worldTransformAtTime(hou.frameToTime(P['T_LAND']))
C = V(mc.extractTranslates()); Rc = mc.extractRotationMatrix3()
Yc = (V(0, 1, 0) * Rc).normalized()
LAND = C + Yc * P['LAND_OFF']
H = C + Yc * P['HOVER_H']
H2 = C + Yc * P['HOV2_H']

def frame_from(fwd, up):
    z = (fwd - up * fwd.dot(up)).normalized()
    x = up.cross(z).normalized()
    y = z.cross(x).normalized()
    m = hou.Matrix3(((x[0], x[1], x[2]), (y[0], y[1], y[2]), (z[0], z[1], z[2])))
    return m

LAND_FWD = V(-0.84, 0.0, 0.53).normalized()
Q_LAND = hou.Quaternion(frame_from(LAND_FWD, Yc))

# ---------------- butterfly base path ----------------
CA = [V(1.60, 1.22, 1.10), V(1.34, 1.12, 0.98), V(1.08, 1.22, 0.86), V(0.84, 1.10, 0.80),
      V(0.62, 1.20, 0.58), V(0.40, 1.06, 0.48), V(0.22, 1.03, 0.30), V(0.03, 0.99, 0.22),
      V(-0.16, 0.95, 0.25), V(-0.13, 0.88, 0.43), V(0.04, 0.91, 0.45), H, H, H]
CE = [H2, H2, H2, H2 + V(0.10, 0.07, 0.08), H2 + V(0.30, 0.22, 0.22), H2 + V(0.62, 0.42, 0.40),
      H2 + V(1.00, 0.62, 0.58), H2 + V(1.40, 0.80, 0.75)]

def base_pos(f):
    if f <= P['T_HOVER']:
        u = (len(CA) - 3) * (f - 1.0) / (P['T_HOVER'] - 1.0)
        return bspline(CA, u)
    if f <= P['T_DESC']:
        return V(H)
    if f <= P['T_LAND']:
        return vlerp(H, LAND, sst((f - P['T_DESC']) / float(P['T_LAND'] - P['T_DESC'])))
    if f <= P['T_LIFT']:
        return V(LAND)
    if f <= P['T_HOV2']:
        return vlerp(LAND, H2, sst((f - P['T_LIFT']) / float(P['T_HOV2'] - P['T_LIFT'])))
    if f <= P['T_AWAY']:
        return V(H2)
    u = (len(CE) - 3) * (f - P['T_AWAY']) / (264.0 - P['T_AWAY']) * 0.62
    return bspline(CE, u)

def bob_amp(f):
    a = 0.011
    a *= 1.0 - sst((f - 98) / 14.0) * 0.75            # 0.011 -> 0.00275 by 112
    a *= 1.0 - sst((f - 110) / 12.0)                  # -> 0 by 122
    if f > P['T_LIFT']:
        a = 0.004 * sst((f - 228) / 10.0) + 0.007 * sst((f - 244) / 12.0)
    return a

def wob_amp(f):
    a = 0.004 * sst((f - 100) / 6.0) * (1 - sst((f - 112) / 10.0))
    a += 0.003 * sst((f - 230) / 6.0) * (1 - sst((f - 242) / 8.0))
    return a

def pos(f):
    p = base_pos(f)
    a = bob_amp(f)
    dy = a * (0.7 * math.sin(2 * math.pi * f / 11.0) + 0.3 * math.sin(2 * math.pi * f / 6.7 + 1.3))
    w = wob_amp(f)
    dx = w * math.sin(2 * math.pi * f / 17.0 + 0.4)
    dz = w * math.sin(2 * math.pi * f / 13.0 + 2.1)
    return p + V(dx, dy, dz)

# ---------------- orientation ----------------
def vel(f):
    return (base_pos(f + 0.5) - base_pos(f - 0.5))

def flight_quat(f):
    v = vel(f)
    fw = V(v[0], v[1] * 0.45, v[2])
    if fw.length() < 1e-6:
        fw = LAND_FWD
    return hou.Quaternion(frame_from(fw.normalized(), V(0, 1, 0)))

def quat(f):
    if f < 92:
        return flight_quat(f)
    if f <= P['T_AWAY']:
        if f < 104:
            w = sst((f - 92) / 12.0)
            return flight_quat(min(f, 101)).slerp(Q_LAND, w)
        return Q_LAND
    w = sst((f - P['T_AWAY']) / 10.0)
    return Q_LAND.slerp(flight_quat(max(f, P['T_AWAY'] + 1.5)), w)

def euler_from_q(q, prev):
    m = hou.Matrix4(q.extractRotationMatrix3())
    r = m.explode(transform_order='srt', rotate_order='xyz')['rotate']
    r = [r[0], r[1], r[2]]
    if prev is not None:
        for i in range(3):
            while r[i] - prev[i] > 180: r[i] -= 360
            while r[i] - prev[i] < -180: r[i] += 360
    return r

# ---------------- wings ----------------
def flap_series():
    out = []; ph = 0.0
    for f in FR:
        # frequency (Hz), centre, amplitude
        if f < 104:
            fq, c, a = 5.0, 32.0, 42.0
        elif f < 132:
            t = sst((f - 104) / 10.0)
            fq = lerp(5.0, 7.5, t); c = lerp(32.0, 34.0, t); a = lerp(42.0, 17.0, t)
            t2 = sst((f - 128) / 6.0)
            a = lerp(a, 0.0, t2); c = lerp(c, 70.0, t2)
        elif f < P['T_LIFT'] - 5:
            fq, a = 7.5, 0.0
            c = lerp(34.0, 70.0, sst((f - 128) / 12.0))
            # slow open/close twice in CUT 4
            if 148 <= f <= 212:
                c = 37.5 + 32.5 * math.cos(2 * math.pi * (f - 148) / 32.0)
        else:
            t = sst((f - 217) / 20.0)
            fq = lerp(1.5, 6.0, t); a = lerp(0.0, 40.0, t); c = lerp(70.0, 33.0, sst((f - 217) / 22.0))
            if f >= 240:
                fq = 6.0; a = 42.0; c = 32.0
        ph += 2 * math.pi * fq / 24.0
        out.append(c + a * math.sin(ph))
    return out

# ---------------- bake butterfly ----------------
poss = {f: pos(f) for f in FR}
eul = {}; prev = None
for f in FR:
    prev = euler_from_q(quat(f), prev); eul[f] = prev
for i, ax in enumerate('xyz'):
    bake(body.parm('t' + ax), [(f, poss[f][i]) for f in FR])
    bake(body.parm('r' + ax), [(f, eul[f][i]) for f in FR])
fl = flap_series()
bake(wl.parm('flap'), list(zip(FR, fl)))
bake(wr.parm('flap'), list(zip(FR, fl)))

# ---------------- hand lowering after butterfly is far ----------------
t_low = None
for f in FR:
    if f > P['T_AWAY'] and (poss[f] - C).length() > 0.45:
        t_low = f + 2; break
bake_hand(t_low)

