hb = girl.node('rig_bone_head'); Le = girl.node('L_eye_null'); Re = girl.node('R_eye_null')
for n in ('headrotatex', 'headrotatey', 'headrotatez'):
    girl.parm(n).deleteAllKeyframes(); girl.parm(n).set(0)

def solve_head(tgt):
    px, py = 0.0, 0.0
    for it in range(4):
        girl.parm('headrotatex').set(px); girl.parm('headrotatey').set(py)
        e = (V(Le.worldTransform().extractTranslates()) + V(Re.worldTransform().extractTranslates())) * 0.5
        d = tgt - e
        # remove eye offset effect by aiming from eye position
        py = math.degrees(math.atan2(d[0], d[2]))
        px = math.degrees(math.atan2(-d[1], math.hypot(d[0], d[2])))
    return px, py

ideal = {}
for f in FR:
    fs = max(1, f - P['HEAD_LAG'])
    ideal[f] = solve_head(poss[fs])
ENTER = P.get('ENTER', 22)
raw = {}
for f in FR:
    px, py = ideal[f]
    px = clamp(px, -35, 45); py = clamp(py, -70, 70)
    w = sst((f - ENTER) / 16.0)
    raw[f] = (lerp(14.0, px, w), lerp(0.0, py, w))
# light symmetric smoothing
K = [1, 4, 6, 4, 1]
sm = {}
for f in FR:
    sx = sy = sw = 0.0
    for j, k in zip(range(-2, 3), K):
        g = clamp(f + j, 1, 264); sx += raw[g][0] * k; sy += raw[g][1] * k; sw += k
    sm[f] = (sx / sw, sy / sw)
tilt = {f: 8.0 * (sst((f - 152) / 16.0) - sst((f - 194) / 16.0)) for f in FR}
bake(girl.parm('headrotatex'), [(f, sm[f][0]) for f in FR])
bake(girl.parm('headrotatey'), [(f, sm[f][1]) for f in FR])
bake(girl.parm('headrotatez'), [(f, tilt[f]) for f in FR])

hou.setFrame(1)
result = dict(C=list(C), Yc=list(Yc), t_low=t_low, LAND=list(LAND))
print(result)

